arguments.newText:
uses_heavy_media_processor() {
  local command="$1"
  local normalized

  # Match common resource-intensive image/video tools as command tokens. This
  # deliberately checks the manifest command before placeholder expansion.
  normalized="$(printf '%s' "$command" | tr -c '[:alnum:]_./-' ' ')"

  case " $normalized " in
    *" ffmpeg "*|*" magick "*|*" convert "*|*" gm "*|*" vips "*|*" cwebp "*|*" avifenc "*|*" oxipng "*|*" pngquant "*|*" jpegtran "*|*" gifsicle "*)
      return 0
      ;;
    */ffmpeg\ *|*/magick\ *|*/convert\ *|*/gm\ *|*/vips\ *|*/cwebp\ *|*/avifenc\ *|*/oxipng\ *|*/pngquant\ *|*/jpegtran\ *|*/gifsicle\ *)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

uses_template_and_target() {
  local command="$1"

  [[ "$command" == *'{template}'* && "$command" == *'{target}'* ]]
}

